type ShellToken = { value: string; operator: boolean };
function shellTokens(command: unknown): ShellToken[] | null {
  if (typeof command !== "string" || command.length > 65536) return null;
  if (command.includes("`") || command.includes("$(")) return null;
  const out: ShellToken[] = [];
  let current = "";
  let quote = "";
  let escaped = false;
  const pushWord = () => {
    if (current) out.push({ value: current, operator: false });
    current = "";
  };
  for (let i = 0; i < command.length; i++) {
    const ch = command[i];
    if (escaped) { current += ch; escaped = false; continue; }
    if (ch === "\\" && quote !== "\'") { escaped = true; continue; }
    if (quote) {
      if (ch === quote) quote = ""; else current += ch;
      continue;
    }
    if (ch === "\'" || ch === '"') { quote = ch; continue; }
    if (/\s/.test(ch)) { pushWord(); continue; }
    if ("<>|;&".includes(ch)) {
      pushWord();
      let op = ch;
      if (i + 1 < command.length && (command[i + 1] === ch || (ch === "&" && command[i + 1] === ">"))) op += command[++i];
      out.push({ value: op, operator: true });
    } else current += ch;
    if (out.length > 256) return null;
  }
  if (escaped || quote) return null;
  pushWord();
  return out.length <= 256 ? out : null;
}

function shellWriteTargets(tokens: ShellToken[]): string[] | null {
  const targets: string[] = [];
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (token.operator && /^(?:>|>>|&>)$/.test(token.value)) {
      const target = tokens[++i];
      if (!target || target.operator) return null;
      targets.push(target.value);
      continue;
    }
    const commandPosition = i === 0 || (tokens[i - 1].operator && /^(?:\||\|\||;|&&)$/.test(tokens[i - 1].value));
    if (commandPosition && !token.operator && /^(?:.*\/)?tee$/.test(token.value)) {
      let sawTarget = false;
      for (let j = i + 1; j < tokens.length && !tokens[j].operator; j++) {
        const value = tokens[j].value;
        if (!sawTarget && value.startsWith("-")) continue;
        sawTarget = true;
        targets.push(value);
      }
      if (!sawTarget) return null;
    }
  }
  return targets;
}

